//! The Rust stream segmenter must agree with the Python one it was ported from.
//!
//! `tests/golden/stream_splitter.json` is generated by
//! `scratch/gen_stream_golden.py` from the real `MarkdownStreamSplitter`; each
//! step records what Python committed and what it kept pending after a delta.

use argent_tui::stream::StreamState;
use serde_json::Value;

fn golden() -> Value {
    let raw = include_str!("golden/stream_splitter.json");
    serde_json::from_str(raw).expect("golden json")
}

#[test]
fn every_golden_case_matches_the_python_splitter() {
    let g = golden();
    let cases = g.as_object().expect("object of cases");
    assert!(cases.len() >= 10, "golden file is suspiciously small");

    for (name, case) in cases {
        let mut buf = String::new();
        let mut st = StreamState::default();

        for (n, step) in case["steps"].as_array().unwrap().iter().enumerate() {
            let delta = step["delta"].as_str().unwrap();
            let want_committed = step["committed"].as_str().unwrap();
            let want_pending = step["pending"].as_str().unwrap();

            buf.push_str(delta);
            let before = st.chunks.len();
            let added = st.advance(&buf);
            let got_committed = if added {
                st.chunk(&buf, st.chunks.len() - 1).to_string()
            } else {
                String::new()
            };

            assert_eq!(
                got_committed, want_committed,
                "{name} step {n}: committed text differs (delta {delta:?})"
            );
            assert_eq!(
                st.pending(&buf),
                want_pending,
                "{name} step {n}: pending tail differs"
            );
            assert!(st.chunks.len() <= before + 1, "{name}: one advance, one chunk");
        }

        let want_final = case["final"].as_str().unwrap();
        let got_final = if st.finalize(&buf) {
            st.chunk(&buf, st.chunks.len() - 1).to_string()
        } else {
            String::new()
        };
        assert_eq!(got_final, want_final, "{name}: finalize remainder differs");
    }
}
